public class WordWrapperTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void broke(String label, Throwable t) {
        System.out.println("FAIL  " + label + " -- expected a value but got " + t.getClass().getSimpleName());
        failures++;
    }

    public static void main(String[] args) {
        try {
            check("wrap(\"the quick brown fox jumps\", 10)", "[the quick, brown fox, jumps]",
                    WordWrapper.wrap("the quick brown fox jumps", 10).toString());
            check("exact fit at the width", "[hello world]", WordWrapper.wrap("hello world", 11).toString());
            check("one over the width", "[hello, world]", WordWrapper.wrap("hello world", 10).toString());
            check("word longer than width stays whole", "[supercalifragilistic, is, long]",
                    WordWrapper.wrap("supercalifragilistic is long", 5).toString());
            check("runs of whitespace collapse", "[spaced out]", WordWrapper.wrap("  spaced   out  ", 20).toString());
            check("empty text", "[]", WordWrapper.wrap("", 10).toString());
            check("blanks only", "[]", WordWrapper.wrap("   ", 10).toString());
            check("width of 1", "[a, b, c]", WordWrapper.wrap("a b c", 1).toString());
        } catch (Throwable t) {
            broke("wrap", t);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

